-- Multiverse Portal RPG: 5 scenarios + 60 characters (plan 2026-10-26)
insert into public.game_scenarios (id, game, seq, title, inspiration, story, setting, stages, class_plan, asset_ids,
  rounds, minutes_per_round, character_count, active, plan_version)
select e->>0, 'multiverse_portal', (e->>1)::smallint, e->>2, e->>3, e->>4, e->>5, e->6, e->7,
  array(select jsonb_array_elements_text(e->8)), 6, 5, 12, true, 2
from jsonb_array_elements($j$[["mv-01",1,"Lâu Đài Sương Mù","File mục I.2 (nữ chiến binh 3D, diệt Boss mở cổng Stencil Portal); thế giới lâu đài sương mù đã có.","Chúa Tể Vết Nứt đã đánh cắp Cuốn Sách Ngôn Từ, khiến chữ nghĩa trong vương quốc bắt đầu biến mất. Nữ chiến binh Scarlet cùng các bạn lần theo hắn vào Lâu Đài Sương Mù. Mỗi đòn đánh trúng làm rơi một trang sách, và mỗi trang mang một từ được cứu lại. Khi Chúa Tể yếu đi, hắn xé rách không gian và bỏ chạy qua vết nứt sang một thế giới khác. Scarlet phải lấy lại đủ trang sách trước khi chuông lâu đài điểm 12 tiếng.","Lâu đài gothic đổ nát trên đảo bay, sương tím phủ lối đá, cửa sổ kính màu vỡ, đèn ma trơi xanh. Tiếng chuông xa vọng lại. Bên kia hành lang kính màu là khu rừng phép lấp lánh; tường lâu đài nứt thành vết sáng.",[{"n":1,"title":"Cổng lâu đài","minutes":5,"optional":false,"goal":"Vào lâu đài, gặp lính canh sương.","beats":["Lính canh làm bằng sương, tan khi trúng đòn.","Thầy Thuốc Lục, nữ tiên rừng cầm trượng, trao thảo dược hồi máu: đọc đúng tên thảo dược để nhận.","Đuốc cháy dọc tường lâu đài: câu đúng làm ngọn lửa sáng, sương lui ra khỏi cổng."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Mở cổng.","vocab":["castle","gate","fog","healer","herb","torch","castle wall"],"assets":["mv_world_castle","mv_hero_scarlet","mv_npc_druid_elf","mv_torch","mv_torch_2","mv_torch_3","mv_castle_module","mv_castle_module_2"],"subtitles":[{"en":"Scarlet reaches the castle gate in the fog.","vi":"Scarlet đến cổng lâu đài trong sương mù.","parts":["Scarlet đến ",["gate","cổng",0]," ",["castle","lâu đài",1]," trong ",["fog","sương mù",2],"."]},{"en":"The healer gives you an herb to heal yourself.","vi":"Thầy thuốc đưa cho bạn một nhành thảo dược để chữa lành.","parts":["Thầy thuốc đưa cho bạn một nhành ",["herb","thảo dược",3]," để ",["heal","chữa lành",2],"."]}]},{"n":2,"title":"Hành lang kính màu","minutes":5,"optional":false,"goal":"Đánh bóng ma trên hành lang.","beats":["Mỗi trang sách rơi ra một từ.","Cửa kính mở ra khu rừng phép: đọc đúng chữ thì lối đi hiện.","Phòng khách cổ điển hiện ra sau tấm kính màu: ghế bành và ghế sofa là nơi giấu các trang sách rơi."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Trang sách 1-3.","vocab":["page","word","save","enchanted","forest","sofa","armchair"],"assets":["mv_world_castle","mv_world_enchanted_candidate","mv_salon_furniture","mv_salon_furniture_2"],"subtitles":[{"en":"Each correct word saves a page from the ghosts.","vi":"Mỗi từ đúng sẽ cứu một trang sách khỏi bóng ma.","parts":["Mỗi ",["word","từ",0]," đúng sẽ ",["save","cứu",1]," một ",["page","trang sách",2]," khỏi bóng ma."]},{"en":"The colored glass makes the hallway look like an enchanted forest.","vi":"Ánh kính màu làm hành lang như một khu rừng phù phép.","parts":["Ánh kính màu làm hành lang như một ",["forest","khu rừng",1]," ",["enchanted","phù phép",4],"."]}]},{"n":3,"title":"Chúa Tể xuất hiện","minutes":5,"optional":false,"goal":"Đối đầu Chúa Tể Vết Nứt pha 1.","beats":["Thanh máu Boss lớn.","Lính Sương lờ mờ hiện ra trong sương: đọc đúng chữ trên khiên mờ để xua chúng đi."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Chí mạng mở Kỹ năng.","vocab":["boss","attack","shield","mist","guard"],"assets":["mv_boss","mv_minion_shadow"],"subtitles":[{"en":"The Rift Lord appears! Raise your shield.","vi":"Chúa Tể Vết Nứt xuất hiện! Giơ khiên lên.","parts":[["Boss","Chúa Tể",1]," Vết Nứt xuất hiện! Giơ ",["shield","khiên",1]," lên."]},{"en":"Use the right answer to attack through the mist.","vi":"Dùng đáp án đúng để tấn công qua làn sương.","parts":["Dùng đáp án đúng để ",["attack","tấn công",1]," qua làn ",["mist","sương",3],"."]}]},{"n":4,"title":"Pha 2: Cơn thịnh nộ","minutes":5,"optional":false,"goal":"Boss dưới 50%: đổi dạng, đánh mạnh hơn.","beats":["Sai 3 câu liền: Boss nổi giận, gợi ý sâu hơn."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Kỹ năng Mắt Sự Thật.","vocab":["angry","phase","strong"],"assets":["mv_boss","fx_spark"],"subtitles":[{"en":"The lord is angry and stronger: this is phase two.","vi":"Chúa Tể tức giận và mạnh hơn: đây là pha hai.","parts":["Chúa Tể ",["angry","tức giận",1]," và mạnh hơn: đây là ",["phase","pha",3]," hai."]},{"en":"Now he is very strong, but do not be afraid!","vi":"Giờ hắn rất mạnh, đừng sợ!","parts":["Giờ hắn rất ",["strong","mạnh",1],", đừng sợ!"]}]},{"n":5,"title":"Vết nứt mở","minutes":5,"optional":false,"goal":"Boss xé không gian bỏ chạy: Scarlet nhảy theo qua cổng.","beats":["Hiệu ứng cổng Stencil.","Vết nứt trên tường mở rộng: mỗi câu đúng làm nó khép lại một đoạn."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Thế giới mới hé lộ.","vocab":["portal","jump","chase","crack","wall"],"assets":["mv_world_cyberpunk","mv_wall_breach"],"subtitles":[{"en":"The crack opens! Scarlet jumps into the portal.","vi":"Vết nứt mở ra! Scarlet nhảy vào cổng.","parts":[["Crack","Vết nứt",2]," mở ra! Scarlet ",["jump","nhảy",0]," vào ",["portal","cổng",2],"."]},{"en":"Chase the lord and do not let him escape.","vi":"Đuổi theo Chúa Tể, đừng để hắn thoát.","parts":[["Chase","Đuổi theo",2]," Chúa Tể, đừng để hắn thoát."]}]},{"n":6,"title":"Chuông 12 tiếng","minutes":5,"optional":false,"goal":"Đánh bại Boss, lấy lại Cuốn Sách Ngôn Từ.","beats":["Chữ nghĩa trở lại vương quốc.","Công Chúa Ngôn nhảy mừng khi Cuốn Sách Ngôn Từ trở lại đủ trang."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Danh hiệu \"Người Giữ Sách\".","vocab":["victory","book","return","princess"],"assets":["mv_world_castle","anim_cheer","char_kid_dancer"],"subtitles":[{"en":"The bell rings: victory! The book is back.","vi":"Chuông ngân: chiến thắng! Cuốn sách đã về.","parts":["Chuông ngân: ",["victory","chiến thắng",2],"! Cuốn ",["book","sách",0]," đã về."]},{"en":"The princess returns to the castle amid cheers.","vi":"Công chúa trở về lâu đài trong tiếng reo vui.","parts":["Công ",["princess","chúa",2]," ",["return","trở về",2]," lâu đài trong tiếng reo vui."]}]},{"n":7,"title":"Chặng phụ: Thư viện tầng hầm","minutes":5,"optional":true,"goal":"Kéo dài: đánh lính sương trong thư viện.","beats":["Câu nhanh."],"question_hook":"Câu hỏi hiện thành ấn phép trên kiếm của Scarlet như trận chính. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["library","shelf"],"assets":["mv_world_castle"],"subtitles":[{"en":"Fight the fog soldiers among the shelves in the library.","vi":"Đánh bọn lính sương giữa các kệ sách trong thư viện.","parts":["Đánh bọn lính sương giữa các ",["shelf","kệ sách",2]," trong ",["library","thư viện",1],"."]}]},{"n":8,"title":"Chặng phụ: Viết lại trang sách","minutes":5,"optional":true,"goal":"Viết lại một trang sách bằng câu của mình.","beats":["Trang sách in vào hồ sơ học viên."],"question_hook":"Mỗi em viết hoặc chọn câu tiếng Anh của mình trên trang sách phép. Câu viết, không tính thua.","reward":"Huy hiệu \"Nhà Văn Lâu Đài\".","vocab":["once upon a time","hero"],"assets":["mv_world_castle"],"subtitles":[{"en":"Once upon a time, there was a brave hero.","vi":"Ngày xửa ngày xưa, có một anh hùng dũng cảm.","parts":[["Once upon a time","Ngày xửa ngày xưa",3],", có một ",["hero","anh hùng",2]," dũng cảm."]}]}],{},["anim_cheer","char_kid_dancer","fx_spark","mv_boss","mv_castle_module","mv_castle_module_2","mv_hero_scarlet","mv_minion_shadow","mv_npc_druid_elf","mv_salon_furniture","mv_salon_furniture_2","mv_torch","mv_torch_2","mv_torch_3","mv_wall_breach","mv_world_castle","mv_world_cyberpunk","mv_world_enchanted_candidate"]],["mv-02",2,"Thành Phố Neon Đêm Mưa","Thế giới cyberpunk neon đã có trong manifest; cổng không gian.","Chạy qua vết nứt, Chúa Tể Vết Nứt trốn vào Thành Phố Neon và chiếm tháp truyền tin. Hắn đổi chữ trên mọi bảng hiệu thành mật mã, làm người dân lạc đường. Scarlet và tổ đội phải nhảy qua mái nhà, sửa bảng hiệu bằng câu trả lời đúng và leo lên tháp. Trên đỉnh tháp, Chúa Tể triệu hồi robot bảo vệ, rồi lại xé không gian định trốn sang sa mạc. Lần này Scarlet có Kỹ năng Khóa Cổng, nếu chuỗi đúng đủ dài.","Thành phố tương lai đêm mưa, bảng neon hồng xanh, xe bay, mái nhà ướt phản chiếu ánh đèn. Tiếng mưa và nhạc điện tử xa.",[{"n":1,"title":"Hẻm neon","minutes":5,"optional":false,"goal":"Đáp xuống hẻm neon, sửa bảng hiệu đầu tiên.","beats":["Bảng hiệu sáng đúng chữ.","Tòa nhà hoang trong hẻm neon là chỗ ẩn của robot: chạm đúng cửa sổ phát sáng để vào."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Bản đồ thành phố.","vocab":["city","sign","neon","building","ruin"],"assets":["mv_world_cyberpunk","mv_hero_scarlet","mv_ruin_building"],"subtitles":[{"en":"Land in the neon city and fix the first sign.","vi":"Đáp xuống thành phố đèn neon: sửa bảng hiệu đầu tiên.","parts":["Đáp xuống ",["city","thành phố",1]," ",["neon","đèn neon",3],": sửa ",["sign","bảng hiệu",1]," đầu tiên."]},{"en":"Each building has a missing letter.","vi":"Mỗi tòa nhà có một chữ bị mất.","parts":["Mỗi ",["building","tòa nhà",2]," có một chữ bị mất."]}]},{"n":2,"title":"Mái nhà mưa","minutes":5,"optional":false,"goal":"Nhảy qua mái nhà, tránh drone.","beats":["Drone soi đèn đỏ.","Một căn phòng neon trên mái nhà: bật đúng bảng hiệu thì drone rời đi."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Giày phản lực.","vocab":["jump","roof","rain","room","neon sign"],"assets":["mv_world_cyberpunk","mv_cyber_room"],"subtitles":[{"en":"Jump across the roofs, avoiding the rain and the drones.","vi":"Nhảy qua các mái nhà, tránh mưa và máy bay không người lái.","parts":[["Jump","Nhảy",0]," qua các mái nhà, tránh ",["rain","mưa",0]," và máy bay không người lái."]},{"en":"Careful, the roof is very slippery!","vi":"Cẩn thận, mái nhà trơn lắm!","parts":["Cẩn thận, ",["roof","mái nhà",2]," trơn lắm!"]}]},{"n":3,"title":"Robot bảo vệ","minutes":5,"optional":false,"goal":"Đánh robot bảo vệ tháp.","beats":["Robot có khiên năng lượng."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Phá khiên.","vocab":["robot","shield","break"],"assets":["mv_boss"],"subtitles":[{"en":"The guard robot raises its shield to block the way.","vi":"Người máy bảo vệ giơ khiên chắn đường.","parts":[["Robot","Người máy",1]," bảo vệ giơ ",["shield","khiên",1]," chắn đường."]},{"en":"Answer correctly to break the shield.","vi":"Trả lời đúng để phá vỡ tấm khiên.","parts":["Trả lời đúng để ",["break","phá vỡ",2]," tấm khiên."]}]},{"n":4,"title":"Đỉnh tháp","minutes":5,"optional":false,"goal":"Đối đầu Chúa Tể pha 1.","beats":["Mưa tạo sấm khi chí mạng."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Chí mạng sấm.","vocab":["tower","top","thunder"],"assets":["mv_boss","fx_spark"],"subtitles":[{"en":"At the top of the tower, thunder crashes!","vi":"Lên đỉnh tháp, sấm nổ vang!","parts":["Lên ",["top","đỉnh",1]," ",["tower","tháp",2],", ",["thunder","sấm",3]," nổ vang!"]},{"en":"The lord roars: You will never make it!","vi":"Chúa Tể gầm lên: Ngươi không qua nổi đâu!","parts":[["Lord","Chúa Tể",3]," gầm lên: Ngươi không qua nổi đâu!"]}]},{"n":5,"title":"Pha 2 và Khóa Cổng","minutes":5,"optional":false,"goal":"Boss dưới 50% mở cổng; chuỗi 5 câu đúng khóa cổng 20 giây.","beats":["Khóa thành công = sát thương gấp đôi."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Kỹ năng Khóa Cổng.","vocab":["lock","chain","combo"],"assets":["mv_boss","mv_world_desert"],"subtitles":[{"en":"Answer five questions in a row to lock the portal with a chain.","vi":"Trả lời liền năm câu đúng để khóa cổng bằng một chuỗi.","parts":["Trả lời liền năm câu đúng để ",["lock","khóa",2]," cổng bằng một ",["chain","chuỗi",3],"."]},{"en":"Keep the combo going for twenty seconds!","vi":"Giữ chuỗi liên tiếp trong hai mươi giây!","parts":["Giữ ",["combo","chuỗi liên tiếp",3]," trong hai mươi giây!"]}]},{"n":6,"title":"Thành phố sáng lại","minutes":5,"optional":false,"goal":"Đánh bại Chúa Tể, mọi bảng hiệu sáng đúng chữ.","beats":["Pháo hoa neon."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Danh hiệu \"Anh Hùng Neon\".","vocab":["light","city","saved"],"assets":["mv_world_cyberpunk","anim_cheer"],"subtitles":[{"en":"All the lights are back on the signs!","vi":"Mọi ánh đèn sáng lại trên các bảng hiệu!","parts":["Mọi ",["light","ánh đèn",1]," sáng lại trên các ",["sign","bảng hiệu",1],"!"]},{"en":"The whole city cheers and thanks the heroes.","vi":"Cả thành phố reo hò cảm ơn các anh hùng.","parts":["Cả ",["city","thành phố",1]," reo hò cảm ơn các anh hùng."]}]},{"n":7,"title":"Chặng phụ: Đường đua xe bay","minutes":5,"optional":true,"goal":"Kéo dài: đuổi Quạ Tím bằng xe bay.","beats":["Câu nhanh."],"question_hook":"Câu hỏi hiện thành ấn phép trên kiếm của Scarlet như trận chính. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["fly","chase"],"assets":["mv_world_cyberpunk"],"subtitles":[{"en":"Fly after the Purple Crow in your flying car and chase it fast!","vi":"Bay theo Quạ Tím bằng xe bay, đuổi thật nhanh!","parts":[["Fly","Bay",1]," theo Quạ Tím bằng xe bay, ",["chase","đuổi",2]," thật nhanh!"]}]},{"n":8,"title":"Chặng phụ: Bảng hiệu của em","minutes":5,"optional":true,"goal":"Thiết kế một bảng hiệu tiếng Anh cho thành phố.","beats":["Bảng hiệu treo trong game."],"question_hook":"Mỗi em viết hoặc chọn câu tiếng Anh của mình trên trang sách phép. Câu viết, không tính thua.","reward":"Huy hiệu \"Nhà Thiết Kế Neon\".","vocab":["open","welcome","shop"],"assets":["mv_world_cyberpunk"],"subtitles":[{"en":"This sign hangs in front of a small shop: Open or Welcome?","vi":"Bảng này treo trước một cửa hàng nhỏ: Mở cửa hay Chào mừng?","parts":["Bảng này treo trước một ",["shop","cửa hàng",1]," nhỏ: ",["Open","Mở cửa",1]," hay ",["Welcome","Chào mừng",1],"?"]}]}],{},["anim_cheer","fx_spark","mv_boss","mv_cyber_room","mv_hero_scarlet","mv_npc_druid_elf","mv_ruin_building","mv_world_cyberpunk","mv_world_desert"]],["mv-03",3,"Tàn Tích Sa Mạc Cát Vàng","Thế giới sa mạc tàn tích trong manifest; cổng không gian.","Vết nứt cuối cùng đưa Chúa Tể Vết Nứt đến Tàn Tích Sa Mạc, nơi chôn Đá Ngữ Pháp cổ. Nếu hắn chạm được viên đá, mọi câu văn trong đa vũ trụ sẽ đảo lộn trật tự. Scarlet phải vượt bão cát, giải câu đố trên các bức tượng đá để mở cửa kim tự tháp trước hắn. Trong lòng kim tự tháp, những bậc thang chỉ hiện ra khi câu được sắp xếp đúng trật tự. Trận cuối diễn ra quanh Đá Ngữ Pháp, mỗi đòn đúng làm viên đá sáng lên che chở Scarlet.","Sa mạc cát vàng, kim tự tháp đổ nát, tượng đá khổng lồ vùi nửa người trong cát, ốc đảo xanh xa xa. Nắng gắt, bão cát nổi lên từng đợt. Giữa bão cát thấp thoáng một cù lao xanh có cọ và gốc cây cổ: ốc đảo thật.",[{"n":1,"title":"Bão cát","minutes":5,"optional":false,"goal":"Vượt bão cát đến tàn tích.","beats":["Cát che tầm nhìn, câu đúng soi đường."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Khăn che cát.","vocab":["desert","sand","storm"],"assets":["mv_world_desert","mv_hero_scarlet"],"subtitles":[{"en":"Sand is flying everywhere! A strong storm is blowing.","vi":"Cát bay mù mịt! Gió bão thổi mạnh.","parts":[["Sand","Cát",0]," bay mù mịt! Gió ",["storm","bão",2]," thổi mạnh."]},{"en":"Cover your face and walk toward the ruins in the desert.","vi":"Che mặt và đi về phía tàn tích giữa sa mạc.","parts":["Che mặt và đi về phía tàn tích giữa ",["desert","sa mạc",1],"."]}]},{"n":2,"title":"Tượng đá","minutes":5,"optional":false,"goal":"Giải câu đố trên tượng đá.","beats":["Tượng mở mắt khi trả lời đúng.","Tấm đá cát nằm nghiêng làm bục đứng cho tượng đá; đặt đúng chữ thì tượng mới nhúc nhích.","Một ngôi đền cổ thu nhỏ hiện sau tượng đá: đặt đúng chữ để mở cửa đền."],"question_hook":"Câu đố khắc trên tượng; đúng = tượng nhường đường.","reward":"Chìa khóa kim tự tháp.","vocab":["statue","riddle","ancient","slab","sand","temple","ruin"],"assets":["mv_world_desert","ground_sand_slab","mv_world_ruin_candidate"],"subtitles":[{"en":"The ancient stone statue asks a riddle.","vi":"Tượng đá cổ hỏi một câu đố.","parts":[["Statue","Tượng",2]," đá cổ hỏi một ",["riddle","câu đố",3],"."]},{"en":"Answer correctly to open the temple door.","vi":"Trả lời đúng để mở cửa ngôi đền.","parts":["Trả lời đúng để mở cửa ngôi ",["temple","đền",2],"."]}]},{"n":3,"title":"Bậc thang trật tự","minutes":5,"optional":false,"goal":"Sắp xếp câu đúng để bậc thang hiện ra.","beats":["Hợp câu sắp xếp (reorder).","Xa xa sau sa mạc là những mái đình giữa núi: đọc đúng thứ tự thì bậc thang dẫn tới đó."],"question_hook":"Mỗi câu xếp đúng hiện một bậc thang.","reward":"Lên tầng trên.","vocab":["order","stairs","climb","pavilion","mountain"],"assets":["mv_world_desert","mv_scene"],"subtitles":[{"en":"Put the words of the sentence in the right order.","vi":"Sắp xếp đúng thứ tự các từ trong câu.","parts":["Sắp xếp đúng ",["order","thứ tự",1]," các từ trong câu."]},{"en":"Each time you are right, a stair appears for you to climb.","vi":"Mỗi lần đúng, một bậc thang hiện ra để leo.","parts":["Mỗi lần đúng, một bậc ",["stairs","thang",1]," hiện ra để ",["climb","leo",1],"."]}]},{"n":4,"title":"Chúa Tể pha 1","minutes":5,"optional":false,"goal":"Đối đầu Chúa Tể quanh Đá Ngữ Pháp.","beats":["Đá sáng lên theo đòn đúng.","Thầy Thuốc Lục pha nước thảo dược ở ốc đảo: mỗi câu đúng là một bình hồi sức cho tổ đội."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Khiên Đá Ngữ Pháp.","vocab":["grammar","stone","glow","oasis","heal"],"assets":["mv_boss","mv_npc_druid_elf"],"subtitles":[{"en":"The Grammar Stone glows when you answer correctly.","vi":"Đá Ngữ Pháp phát sáng khi bạn trả lời đúng.","parts":["Đá ",["grammar","Ngữ Pháp",3]," ",["glow","phát sáng",2]," khi bạn trả lời đúng."]},{"en":"Drink water at the oasis to heal.","vi":"Uống nước ở ốc đảo để hồi sức.","parts":["Uống nước ở ",["oasis","ốc đảo",3]," để ",["heal","hồi sức",2],"."]}]},{"n":5,"title":"Pha 2: Bọ cạp cát","minutes":5,"optional":false,"goal":"Boss triệu hồi bọ cạp cát khổng lồ.","beats":["Bọ cạp chặn đòn; trinh sát tìm điểm yếu."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Chí mạng điểm yếu.","vocab":["scorpion","weak point"],"assets":["mv_boss","fx_spark"],"subtitles":[{"en":"A giant sand scorpion appears!","vi":"Bọ cạp cát khổng lồ xuất hiện!","parts":[["Scorpion","Bọ cạp",2]," cát khổng lồ xuất hiện!"]},{"en":"Hit its weak point with the right answer.","vi":"Đánh vào điểm yếu của nó bằng đáp án đúng.","parts":["Đánh vào ",["weak point","điểm yếu",3]," của nó bằng đáp án đúng."]}]},{"n":6,"title":"Ốc đảo","minutes":5,"optional":false,"goal":"Đánh bại Boss, đem Đá Ngữ Pháp về ốc đảo an toàn.","beats":["Cát lặng, ốc đảo nở hoa.","Ốc đảo hiện lên giữa cát: đúng câu thì cọ xanh trở lại."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Danh hiệu \"Người Giữ Đá Ngữ Pháp\".","vocab":["oasis","peace","win","palm tree"],"assets":["mv_world_desert","anim_cheer","mini_large_island"],"subtitles":[{"en":"We win! The oasis is peaceful again.","vi":"Chúng ta thắng! Ốc đảo lại bình yên.","parts":["Chúng ta ",["win","thắng",0],"! Ốc đảo lại ",["peaceful","bình yên",3],"."]},{"en":"Under the palm tree, the whole team rests.","vi":"Dưới bóng cây cọ, cả đội nghỉ ngơi.","parts":["Dưới bóng ",["palm tree","cây cọ",2],", cả đội nghỉ ngơi."]}]},{"n":7,"title":"Chặng phụ: Lạc đà","minutes":5,"optional":true,"goal":"Kéo dài: cưỡi lạc đà đuổi Quạ Tím.","beats":["Câu nhanh."],"question_hook":"Câu hỏi hiện thành ấn phép trên kiếm của Scarlet như trận chính. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["camel","ride"],"assets":["mv_world_desert"],"subtitles":[{"en":"Ride a camel and chase the Purple Crow!","vi":"Cưỡi lạc đà đuổi theo Quạ Tím!","parts":[["Ride","Cưỡi",2]," ",["camel","lạc đà",1]," đuổi theo Quạ Tím!"]}]},{"n":8,"title":"Chặng phụ: Bia đá mới","minutes":5,"optional":true,"goal":"Khắc một câu đúng ngữ pháp lên bia đá.","beats":["Bia đá đặt ở ốc đảo."],"question_hook":"Mỗi em viết hoặc chọn câu tiếng Anh của mình trên trang sách phép. Câu viết, không tính thua.","reward":"Huy hiệu \"Nhà Khảo Cổ Nhí\".","vocab":["carve","sentence"],"assets":["mv_world_desert"],"subtitles":[{"en":"Carve a grammatically correct sentence onto the new stone.","vi":"Khắc một câu đúng ngữ pháp lên bia đá.","parts":[["Carve","Khắc",3]," một ",["sentence","câu",1]," đúng ngữ pháp lên bia đá."]}]}],{},["anim_cheer","fx_spark","ground_sand_slab","mini_large_island","mv_boss","mv_hero_scarlet","mv_npc_druid_elf","mv_scene","mv_world_desert","mv_world_ruin_candidate"]],["mv-04",4,"Cổng Vỡ Đuổi Bắt","Cổng Stencil xé không gian; chuyển cảnh mượt giữa lâu đài và thành phố neon.","Chúa Tể Vết Nứt học được cách mở nhiều cổng cùng lúc, và hai thế giới lâu đài và thành phố neon bắt đầu va vào nhau. Scarlet phải đuổi theo hắn qua những mảnh thế giới trôi nổi, mỗi lần nhảy cổng là sang một thế giới khác. Cổng chỉ đứng yên khi tổ đội trả lời đúng, sai thì cổng rung và đổi chỗ. Giữa đường, Quạ Tím bày bẫy cổng giả dẫn sang chỗ không lối thoát. Đóng được cổng cuối, hai thế giới sẽ tách ra và Chúa Tể bị kẹt giữa.","Không gian nứt vỡ: một nửa là lâu đài sương mù, một nửa là thành phố neon, các mảnh thế giới trôi lơ lửng nối nhau bằng cầu ánh sáng. Một đảo xanh nhỏ có sông và hải đăng trôi lạc giữa các mảnh vỡ.",[{"n":1,"title":"Mảnh lâu đài","minutes":5,"optional":false,"goal":"Bắt đầu ở mảnh lâu đài trôi nổi.","beats":["Cầu ánh sáng hiện theo câu đúng.","Một mảnh lâu đài trôi lơ lửng, đuốc vẫn cháy trên tường: câu đúng giữ ngọn lửa không tắt."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Cầu ánh sáng.","vocab":["bridge","float","light","torch","tower"],"assets":["mv_world_castle","mv_torch_4","mv_castle_module_3"],"subtitles":[{"en":"You stand on a piece of the castle that is floating.","vi":"Bạn đứng trên mảnh lâu đài đang trôi.","parts":["Bạn đứng trên mảnh lâu đài đang ",["float","trôi",2],"."]},{"en":"A bridge of light connects to the next piece.","vi":"Một cây cầu ánh sáng nối sang mảnh kế tiếp.","parts":["Một ",["bridge","cây cầu",1]," ",["light","ánh sáng",1]," nối sang mảnh kế tiếp."]}]},{"n":2,"title":"Nhảy cổng 1","minutes":5,"optional":false,"goal":"Nhảy sang mảnh thành phố neon.","beats":["Cổng đứng yên khi đúng.","Đấu sĩ Đỏ chỉ đường qua cổng đầu tiên, rồi biến mất vào ánh sáng."],"question_hook":"Câu hỏi trên khung cổng.","reward":"Sang thế giới mới.","vocab":["portal","switch","world","kick"],"assets":["mv_world_cyberpunk","char_crimson_kick"],"subtitles":[{"en":"Jump through the portal to switch to a new world.","vi":"Nhảy qua cổng để đổi sang thế giới mới.","parts":["Nhảy qua ",["portal","cổng",2]," để ",["switch","đổi",3]," sang thế giới mới."]},{"en":"A nice kick opens the way into the neon world.","vi":"Một cú đá đẹp mở đường vào thế giới neon.","parts":["Một cú ",["kick","đá",1]," đẹp mở đường vào ",["world","thế giới",1]," neon."]}]},{"n":3,"title":"Cổng giả của Quạ Tím","minutes":5,"optional":false,"goal":"Phân biệt cổng thật và cổng giả.","beats":["Câu đúng soi ra cổng giả.","Lính Sương canh cầu ánh sáng: trả lời đúng để chúng tan thành sương."],"question_hook":"Câu trắc nghiệm: chọn cổng thật.","reward":"Tránh bẫy.","vocab":["true","false","trap","shadow","bridge"],"assets":["mv_world_castle","mv_world_cyberpunk","mv_minion_shadow"],"subtitles":[{"en":"Which portal is true and which is false?","vi":"Cổng nào thật, cổng nào giả?","parts":["Cổng nào ",["true","thật",2],", cổng nào ",["false","giả",2],"?"]},{"en":"The Purple Crow sets traps in the shadows.","vi":"Quạ Tím đặt bẫy trong bóng tối.","parts":["Quạ Tím đặt ",["trap","bẫy",3]," trong ",["shadow","bóng tối",2],"."]}]},{"n":4,"title":"Chúa Tể giữa hai thế giới","minutes":5,"optional":false,"goal":"Đánh Boss pha 1 trên mảnh vỡ.","beats":["Mảnh vỡ nghiêng khi Boss tấn công.","Scarlet lắp nỏ ấn phép: mỗi câu đúng nạp một mũi tên sáng."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Chí mạng.","vocab":["boss","balance","crossbow","rune"],"assets":["mv_boss","mv_weapon_runecrossbow"],"subtitles":[{"en":"The lord keeps the balance between two worlds.","vi":"Chúa Tể giữ thăng bằng giữa hai thế giới.","parts":["Chúa Tể giữ ",["balance","thăng bằng",3]," giữa hai thế giới."]},{"en":"Fire runes with the crossbow; only the right answer will hit.","vi":"Bắn ký tự phép bằng nỏ, đúng đáp án mới trúng.","parts":["Bắn ",["rune","ký tự phép",3]," bằng ",["crossbow","nỏ",3],", đúng đáp án mới trúng."]}]},{"n":5,"title":"Pha 2: Bão cổng","minutes":5,"optional":false,"goal":"Boss mở hàng loạt cổng nhỏ bắn phép.","beats":["Pháp sư Khiên đỡ đòn khi đúng."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Khiên cổng.","vocab":["shield","many","dodge"],"assets":["mv_boss","fx_spark"],"subtitles":[{"en":"A portal storm! Raise your shield.","vi":"Bão cổng! Giơ khiên lên che chắn.","parts":["Bão cổng! Giơ ",["shield","khiên",1]," lên che chắn."]},{"en":"Many small portals fire spells, so dodge!","vi":"Có rất nhiều cổng nhỏ bắn phép, hãy né!","parts":["Có ",["many","rất nhiều",1]," cổng nhỏ bắn phép, hãy ",["dodge","né",2],"!"]}]},{"n":6,"title":"Đóng cổng cuối","minutes":5,"optional":false,"goal":"Đánh bại Boss, đóng cổng, hai thế giới tách ra.","beats":["Hiệu ứng hai thế giới trượt về chỗ cũ."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Danh hiệu \"Người Đóng Cổng\".","vocab":["close","separate","safe"],"assets":["mv_world_castle","mv_world_cyberpunk","anim_cheer"],"subtitles":[{"en":"Close the last portal!","vi":"Đóng cổng cuối cùng lại!","parts":[["Close","Đóng",1]," cổng cuối cùng lại!"]},{"en":"The two worlds separate and everyone is safe.","vi":"Hai thế giới tách ra và mọi người an toàn.","parts":["Hai thế giới ",["separate","tách ra",3]," và mọi người ",["safe","an toàn",1],"."]}]},{"n":7,"title":"Chặng phụ: Mảnh vỡ lạc","minutes":5,"optional":true,"goal":"Kéo dài: nhặt mảnh vỡ còn sót.","beats":["Câu nhanh.","Mảnh vỡ lạc là một đảo nhỏ có hải đăng: đưa nó về đúng cổng để thắp đèn dẫn đường.","Những tảng đá lơ lửng là mảnh vỡ lạc: đưa từng tảng về đúng cổng."],"question_hook":"Câu hỏi hiện thành ấn phép trên kiếm của Scarlet như trận chính. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["piece","collect","island","lighthouse","floating","stone"],"assets":["mv_world_castle","mini_floating_island","mv_scene_3"],"subtitles":[{"en":"Collect every piece left around the island.","vi":"Nhặt từng mảnh vỡ còn sót quanh hòn đảo.","parts":[["Collect","Nhặt",2]," từng ",["piece","mảnh vỡ",1]," còn sót quanh ",["island","hòn đảo",1],"."]}]},{"n":8,"title":"Chặng phụ: Nhật ký cổng","minutes":5,"optional":true,"goal":"Ghi lại các thế giới đã đi qua.","beats":["Nhật ký lưu vào hồ sơ."],"question_hook":"Mỗi em viết hoặc chọn câu tiếng Anh của mình trên trang sách phép. Câu viết, không tính thua.","reward":"Huy hiệu \"Lữ Khách Đa Vũ Trụ\".","vocab":["visited","saw","met"],"assets":["mv_world_cyberpunk"],"subtitles":[{"en":"Which worlds did you visit and see?","vi":"Em đã ghé thăm và nhìn thấy những thế giới nào?","parts":["Em đã ",["visited","ghé thăm",2]," và ",["saw","nhìn thấy",1]," những thế giới nào?"]}]}],{},["anim_cheer","char_crimson_kick","fx_spark","mini_floating_island","mv_boss","mv_castle_module_3","mv_hero_scarlet","mv_minion_shadow","mv_npc_druid_elf","mv_scene_3","mv_torch_4","mv_weapon_runecrossbow","mv_world_castle","mv_world_cyberpunk"]],["mv-05",5,"Trận Chung Kết Đa Vũ Trụ","Tổng hợp 3 thế giới; trận cuối nhiều pha, cả lớp hợp sức.","Chúa Tể Vết Nứt hợp nhất sức mạnh của cả ba thế giới thành Chúa Tể Hợp Thể, đứng ở trái tim đa vũ trụ. Scarlet và mọi tổ đội từng chiến đấu được triệu tập cho trận chung kết. Mỗi pha của Boss mang sức mạnh một thế giới: sương mù lâu đài, sấm neon, bão cát. Chỉ khi cả lớp cùng góp câu trả lời đúng, ba cổng mới đóng dần và Boss mất sức mạnh. Chiến thắng sẽ trả lại hòa bình cho đa vũ trụ và trao cho Scarlet danh hiệu Người Giữ Cổng.","Trái tim đa vũ trụ: một vòng cung khổng lồ nối ba cổng lâu đài, thành phố neon và sa mạc, bầu trời đầy sao và mảnh thế giới xoay quanh. Khi hòa bình trở lại, một đảo xanh nhỏ có sông và thác nổi lên giữa ba cổng.",[{"n":1,"title":"Triệu tập","minutes":5,"optional":false,"goal":"Các tổ đội tập hợp ở trái tim đa vũ trụ.","beats":["Mỗi tổ đội nhận cờ màu.","Bốn lữ khách từ các thế giới tới điểm triệu tập: ghép đúng tên và đặc điểm từng người.","Các tổ đội tập hợp quanh đuốc trong sân pháo đài: mỗi đội đọc đúng lời triệu tập thì đuốc của đội sáng lên."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Buff tổ đội.","vocab":["gather","team","final","hero","torch","tower"],"assets":["mv_hero_scarlet","mv_world_castle","mv_world_cyberpunk","mv_world_desert","char_iridescent_voyager","char_grovae